INSERT IGNORE INTO sys_role_menu(role_id,menu_id) SELECT r.role_id,m.menu_id FROM sys_role r CROSS JOIN sys_menu m WHERE r.kind='PLATFORM' AND r.factory_id IS NULL AND r.legacy_id IS NOT NULL AND m.legacy_id IS NULL AND EXISTS(SELECT 1 FROM phase1_legacy_sys_role_menu x JOIN phase1_legacy_sys_menu old ON old.id=x.menu_id WHERE x.role_id=r.legacy_id AND old.permission='platform:roles:write');
